using System;
using UnityEngine;

namespace PKR
{
    /// <summary>
    /// Frame-by-frame animation for a fighter (generated by Tools/art/build_all.py, assigned by the editor).
    /// All frames face right, bottom-centre pivot, 32 px per unit. Empty arrays fall back to bodySprite.
    /// </summary>
    [Serializable]
    public class FighterFrames
    {
        public Sprite[] idle = new Sprite[0];
        public Sprite[] run = new Sprite[0];
        public Sprite[] jump = new Sprite[0];
        public Sprite[] fall = new Sprite[0];
        [Tooltip("Wind-up, strike (with the weapon arc), follow-through.")]
        public Sprite[] attack = new Sprite[0];
        [Tooltip("Charge, release.")]
        public Sprite[] special = new Sprite[0];
        public Sprite[] hurt = new Sprite[0];
        [Tooltip("Signature weapon shown in the menus.")]
        public string weaponName = "";

        public bool HasAny => idle != null && idle.Length > 0;

        /// <summary>Frame i of a looping clip, or null when the clip is empty.</summary>
        public static Sprite Pick(Sprite[] clip, int i)
        {
            if (clip == null || clip.Length == 0) return null;
            i %= clip.Length;
            if (i < 0) i += clip.Length;
            return clip[i];
        }
    }
}
